#!/bin/bash
# This script is used to remove rDNA contamination from assemblies generated by hifiasm.
# The resulting assemblies, after rDNA removal, are saved with the .rDNAremoved.fa suffix.


# Process HiFi reads and summarize assembly quality.
# Set input, reference and tool paths for your environment before execution.

wd=/path/to/00.asm
samplelist=/path/to/sample.list
screen_assembly_pl=/path/to/screen-assembly.pl
rdna_fa="/path/to/human-rdna-KY962518.1.fasta.gz"
# Read one record per line; keep backslashes and a final line without a newline.
while IFS= read -r sample <&9 || [[ -n "$sample" ]]; do
    [[ -z "$sample" ]] && continue
mkdir -p "${wd}/rm_rDNA/${sample}/input"
## input file
# hifiasm output: gfa & fa & fai
indir="/path/to/sum"
asm1=${indir}/${sample}.hap1.fa
asm2=${indir}/${sample}.hap2.fa
fai1=${indir}/${sample}.hap1.fa.fai
fai2=${indir}/${sample}.hap2.fa.fai
gfa1=${indir}/${sample}.hap1.gfa
gfa2=${indir}/${sample}.hap2.gfa
awk -F'\t' '{print "path" "\t" $1 "\t" $1}' "$fai1" > "${wd}/rm_rDNA/${sample}/input/${sample}.hap1.scfmap"
awk -F'\t' '{print "path" "\t" $1 "\t" $1}' "$fai2" > "${wd}/rm_rDNA/${sample}/input/${sample}.hap2.scfmap"
>"${wd}/rm_rDNA/${sample}/input/${sample}.hap1.hifi.csv"
>"${wd}/rm_rDNA/${sample}/input/${sample}.hap2.hifi.csv"
## script
script="#!/bin/bash
#SBATCH --job-name=${sample}.asm_rm_rDNA
#SBATCH --partition=batch
#SBATCH --output=${wd}/rm_rDNA/${sample}/rm_rDNA.log
#SBATCH --error=${wd}/rm_rDNA/${sample}/rm_rDNA.err
#SBATCH --mincpus=4
#SBATCH --mem=16g
source /path/to/activate mashmap
cd ${wd}/rm_rDNA/${sample}
perl $screen_assembly_pl \
    --assembly $asm1 \
    --graph $gfa1 \
    --graphmap ${wd}/rm_rDNA/${sample}/input/${sample}.hap1.scfmap \
    --hifi-coverage ${wd}/rm_rDNA/${sample}/input/${sample}.hap1.hifi.csv\
    --contaminant rdna $rdna_fa \
    --output ${sample}.hap1.rDNAremoved \
    --threads 4
perl $screen_assembly_pl \
    --assembly $asm2 \
    --graph $gfa2 \
    --graphmap ${wd}/rm_rDNA/${sample}/input/${sample}.hap2.scfmap \
    --hifi-coverage ${wd}/rm_rDNA/${sample}/input/${sample}.hap2.hifi.csv\
    --contaminant rdna $rdna_fa \
    --output ${sample}.hap2.rDNAremoved \
    --threads 4
"
echo -e "$script" > "${wd}/rm_rDNA/${sample}/rm_rDNA.sh"
echo -e "sbatch ${wd}/rm_rDNA/${sample}/rm_rDNA.sh" >> "${wd}/rm_rDNA/run.sbatch_rDNA.sh"
done 9< "$samplelist"
